import socket,time,json,pathlib,datetime
print('UTC',datetime.datetime.now(datetime.timezone.utc).isoformat(),flush=True)
print('resolver_lines',[l for l in pathlib.Path('/etc/resolv.conf').read_text().splitlines() if l.strip().startswith(('nameserver','options','search'))],flush=True)
for i in range(3):
 t=time.monotonic()
 try:
  result=socket.gethostbyaddr('192.168.1.246');print(json.dumps(dict(iteration=i,operation='reverse',elapsed_seconds=time.monotonic()-t,result=result)),flush=True)
  t=time.monotonic();print(json.dumps(dict(iteration=i,operation='forward',elapsed_seconds=time.monotonic()-t,result=socket.getaddrinfo(result[0],None))),flush=True)
 except Exception as e:print(json.dumps(dict(iteration=i,operation='reverse',elapsed_seconds=time.monotonic()-t,error=repr(e))),flush=True)
